      { q: 'តើលោភមូលចិត្តមានប៉ុន្មានដួង?', a: 'លោភមូលចិត្តមាន ៨ ដួង។' },
      { q: 'តើបុថុជ្ជនមានលោភមូលចិត្តប៉ុន្មានដួង?', a: 'បុថុជ្ជនមានលោភមូលចិត្ត ៨ ដួង។' },
      { q: 'តើអរិយបុគ្គលថ្នាក់ក្រោម ដូចជាសោតាបន្ន សកទាគាមិបុគ្គល អនាគាមិបុគ្គល មានលោភមូលចិត្តប៉ុន្មានដួង?', a: 'អរិយបុគ្គលថ្នាក់ក្រោម ដូចជាសោតាបន្ន សកទាគាមិបុគ្គល អនាគាមិបុគ្គល មានលោភមូលចិត្ត ៤ ដួង គឺដួងណាដែលមានឈ្មោះថា ទិដ្ឋិគតវិប្បយុត្តំ ពីព្រោះមិច្ឆាទិដ្ឋិបានកាត់ឫសដាច់អស់ហើយដោយមគ្គអង្គ ៨។' },
      { q: 'តើព្រះអរហន្តមានលោភមូលចិត្តប៉ុន្មានដួង?', a: 'ព្រះអរហន្តអត់មានលោភមូលចិត្តទេ ព្រោះអកុសលចេតសិកទាំង ១៤ បានកាត់ឫសអស់ហើយដោយមគ្គអង្គ ៨។' },
      { q: 'តើសត្វតិរច្ឆានដូចជាគោ ក្របី សេះ ដំរី ស្រមោច មាន់ ទា ជាដើម មានលោភមូលចិត្តប៉ុន្មានដួង?', a: 'សត្វតិរច្ឆានដូចជាគោ ក្របី សេះ ដំរី ស្រមោច មាន់ ទា ជាដើម មានលោភមូលចិត្ត ៨ ដួង។' },
      { q: 'ក្នុងនិច្ចសីល តើលោភមូលចិត្ត ៨ ដួង ជាហេតុឱ្យដាច់សិក្ខាបទប៉ុន្មាន? អ្វីខ្លះ?', a: 'ក្នុងនិច្ចសីល លោភមូលចិត្ត ៨ ដួង ជាហេតុឱ្យដាច់សិក្ខាបទ ៤ គឺ៖\n១- អទិន្នាទាន ដាច់ដោយ ទោសមូលចិត្ត ២ ដួង និង លោភមូលចិត្ត ៨ ដួង\n២- កាមេសុមិច្ឆាចារ ដាច់ដោយ លោភមូលចិត្ត ៨ ដួង\n៣- មុសាវាទ ដាច់ដោយ ទោសមូលចិត្ត ២ ដួង និង លោភមូលចិត្ត ៨ ដួង\n៤- សុរាមេរយមជ្ជប្បមាទដ្ឋាន ដាច់ដោយ លោភមូលចិត្ត ៨ ដួង' },
    ],
  },
]

function partFiltered(pi) {
  if (!searching.value) return parts[pi].items
  return parts[pi].items.filter(item =>
    item.q.toLowerCase().includes(q.value) ||
    item.a.toLowerCase().includes(q.value)
  )
}

const totalMatches = computed(() => {
  if (!searching.value) return 0
  return parts.reduce((sum, _, pi) => sum + partFiltered(pi).length, 0)
})
</script>
